type InternalTraceSnapshot = {
  spanId: string;
  traceId: string;
  parentSpanId?: string;
  name?: string;
  type: ObservationType;
  environment?: string;
  version?: string;
  release?: string;
  startTimeISO?: string;
  endTimeISO?: string;
  completionStartTime?: string;
  level?: string;
  statusMessage?: string;
  promptName?: string;
  promptVersion?: string;
  modelName?: string;
  modelParameters?: Record<string, unknown>;
  providedUsageDetails?: Record<string, number>;
  providedCostDetails?: Record<string, number>;
  input?: unknown;
  output?: unknown;
  metadata: Record<string, unknown>;
  tags?: string[];
  public?: boolean;
  bookmarked?: boolean;
  userId?: string;
  sessionId?: string;
};

export type MaterializedInternalTrace = {
  rootSpanId: string;
  snapshots: InternalTraceSnapshot[];
};

function isCreateEvent(type: string): boolean {
  return type.endsWith("-create");
}

function getSnapshotType(eventType: string): ObservationType {
  const prefix = eventType.replace(/-(create|update)$/i, "").toUpperCase();
  const parsed = ObservationTypeDomain.safeParse(prefix);
  return parsed.success ? parsed.data : "SPAN";
}

function asIsoTimestamp(value: unknown): string | undefined {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return value.toISOString();
  }

  return asString(value);
}

function getEventTime(
  event: ProcessedTraceEvent,
  body: Record<string, unknown>,
): number {
  const candidates = [body.startTime, body.timestamp, event.timestamp];

  for (const candidate of candidates) {
    if (candidate instanceof Date && !Number.isNaN(candidate.getTime())) {
      return candidate.getTime();
    }

    if (typeof candidate === "string") {
      const parsed = new Date(candidate).getTime();
      if (!Number.isNaN(parsed)) {
        return parsed;
      }
    }
  }

  return 0;
}

function getTimestampMs(timestamp?: string): number {
  if (!timestamp) {
    return 0;
  }

  const parsed = new Date(timestamp).getTime();
  return Number.isNaN(parsed) ? 0 : parsed;
}

function sortEvents(events: ProcessedTraceEvent[]): ProcessedTraceEvent[] {
  return [...events].sort((left, right) => {
    const timeDelta =
      getEventTime(left, left.body) - getEventTime(right, right.body);

    if (timeDelta !== 0) {
      return timeDelta;
    }

    if (isCreateEvent(left.type) === isCreateEvent(right.type)) {
      return 0;
    }

    return isCreateEvent(left.type) ? -1 : 1;
  });
}

function flattenMetadata(value: unknown): {
  names: string[];
  values: Array<string | null | undefined>;
} {
  const metadata = asRecord(value);
  return metadata
    ? flattenJsonToPathArrays(metadata)
    : { names: [], values: [] };
}

function mergeSnapshotEvent(
  snapshot: InternalTraceSnapshot,
  event: ProcessedTraceEvent,
): InternalTraceSnapshot {
  const { body } = event;
  const startTime = asIsoTimestamp(body.startTime);
  const timestamp =
    asIsoTimestamp(body.timestamp) ?? asIsoTimestamp(event.timestamp);
  const metadata = asRecord(body.metadata);

  return {
    ...snapshot,
    traceId: asString(body.traceId) ?? snapshot.traceId,
    parentSpanId: asString(body.parentObservationId) ?? snapshot.parentSpanId,
    type:
      snapshot.type !== "SPAN" ? snapshot.type : getSnapshotType(event.type),
    name: asString(body.name) ?? snapshot.name,
    environment: asString(body.environment) ?? snapshot.environment,
    version: asString(body.version) ?? snapshot.version,
    release: asString(body.release) ?? snapshot.release,
    startTimeISO:
      startTime ?? snapshot.startTimeISO ?? timestamp ?? snapshot.startTimeISO,
    endTimeISO: asIsoTimestamp(body.endTime) ?? snapshot.endTimeISO,
    completionStartTime:
      asIsoTimestamp(body.completionStartTime) ?? snapshot.completionStartTime,
    level: asString(body.level) ?? snapshot.level,
    statusMessage: asString(body.statusMessage) ?? snapshot.statusMessage,
    promptName: asString(body.promptName) ?? snapshot.promptName,
    promptVersion:
      typeof body.promptVersion === "number"
        ? body.promptVersion.toString()
        : (asString(body.promptVersion) ?? snapshot.promptVersion),
    modelName: asString(body.model) ?? snapshot.modelName,
    modelParameters: asRecord(body.modelParameters) ?? snapshot.modelParameters,
    providedUsageDetails:
      asNumberRecord(body.usageDetails) ??
      asNumberRecord(body.usage) ??
      snapshot.providedUsageDetails,
    providedCostDetails:
      asNumberRecord(body.costDetails) ?? snapshot.providedCostDetails,
    input:
      body.input !== undefined && body.input !== null
        ? body.input
        : snapshot.input,
    output:
      body.output !== undefined && body.output !== null
        ? body.output
        : snapshot.output,
    metadata: metadata
      ? { ...snapshot.metadata, ...metadata }
      : snapshot.metadata,
    tags: asStringArray(body.tags) ?? snapshot.tags,
    public: asBoolean(body.public) ?? snapshot.public,
    bookmarked: asBoolean(body.bookmarked) ?? snapshot.bookmarked,
    userId: asString(body.userId) ?? snapshot.userId,
    sessionId: asString(body.sessionId) ?? snapshot.sessionId,
  };
}

export function materializeInternalTrace(params: {
  processedEvents: ProcessedTraceEvent[];
  traceId: string;
}): MaterializedInternalTrace {
  const { processedEvents, traceId } = params;
  const snapshots = new Map<string, InternalTraceSnapshot>();
  const traceCreateEvent = processedEvents.find(
    (e) => e.type === "trace-create",
  );
  const rootSpanId = asString(traceCreateEvent?.body.id) ?? traceId;

  for (const event of sortEvents(processedEvents)) {
    const spanId = asString(event.body.id);

    if (!spanId) {
      continue;
    }

    const existingSnapshot =
      snapshots.get(spanId) ??
      ({
        spanId,
        traceId: asString(event.body.traceId) ?? traceId,
        type: getSnapshotType(event.type),
        metadata: {},
      } satisfies InternalTraceSnapshot);

    snapshots.set(spanId, mergeSnapshotEvent(existingSnapshot, event));
  }

  const orderedSnapshots = [...snapshots.values()].sort((left, right) => {
    if (left.spanId === rootSpanId) {
      return -1;
    }

    if (right.spanId === rootSpanId) {
      return 1;
    }

    return (
      getTimestampMs(left.startTimeISO) - getTimestampMs(right.startTimeISO)
    );
  });

  return { rootSpanId, snapshots: orderedSnapshots };
}

export function buildInternalTraceEventInputs(params: {
  processedEvents: ProcessedTraceEvent[];
  traceId: string;
  projectId: string;
  userId?: string;
  sessionId?: string;
  experimentContext?: InternalTraceExperimentContext;
}): {
  rootSpanId: string;
  eventInputs: InternalTraceEventInput[];
} {
  const { processedEvents, traceId, projectId, experimentContext } = params;
  // Direct write uses original IDs (observation.id === trace.id for root).
  // The experiment backfill job skips traces already in events_core via LEFT ANTI JOIN,
  // so there's no deduplication concern between direct write and backfill.
  const { rootSpanId, snapshots } = materializeInternalTrace({
    processedEvents,
    traceId,
  });
  const rootSnapshot = snapshots.find((s) => s.spanId === rootSpanId);

  if (!rootSnapshot) {
    return { rootSpanId, eventInputs: [] };
  }

  const experimentMetadata = flattenMetadata(experimentContext?.metadata);
  const experimentItemMetadata = flattenMetadata(
    experimentContext?.itemMetadata,
  );
  const source = experimentContext
    ? INTERNAL_TRACE_EXPERIMENT_EVENT_SOURCE
    : INTERNAL_TRACE_EVENT_SOURCE;

  const eventInputs = snapshots.map((snapshot) => {
    const { toolDefinitions, toolArguments } = extractToolsFromObservation(
      snapshot.input,
      snapshot.output,
    );
    const toolCalls = convertCallsToArrays(toolArguments);
    const isRoot = snapshot.spanId === rootSpanId;

    return {
      projectId,
      traceId,
      spanId: snapshot.spanId,
      parentSpanId: isRoot ? undefined : (snapshot.parentSpanId ?? rootSpanId),
      name:
        snapshot.name ??
        (snapshot.type === "GENERATION"
          ? "generation"
          : (rootSnapshot.name ?? "span")),
      type: snapshot.type,
      environment: snapshot.environment ?? rootSnapshot.environment,
      version: snapshot.version ?? rootSnapshot.version,
      release: rootSnapshot.release,
      startTimeISO:
        snapshot.startTimeISO ??
        rootSnapshot.startTimeISO ??
        new Date().toISOString(),
      endTimeISO:
        snapshot.endTimeISO ??
        snapshot.startTimeISO ??
        rootSnapshot.endTimeISO ??
        rootSnapshot.startTimeISO ??
        new Date().toISOString(),
      completionStartTime: snapshot.completionStartTime,
      traceName: rootSnapshot.name,
      tags: rootSnapshot.tags ?? [],
      bookmarked: rootSnapshot.bookmarked,
      public: rootSnapshot.public,
      userId: snapshot.userId ?? rootSnapshot.userId ?? params.userId,
      sessionId:
        snapshot.sessionId ?? rootSnapshot.sessionId ?? params.sessionId,
      level: snapshot.level ?? "DEFAULT",
      statusMessage: snapshot.statusMessage,
      promptName: snapshot.promptName,
      promptVersion: snapshot.promptVersion,
      modelName: snapshot.modelName,
      modelParameters: snapshot.modelParameters,
      providedUsageDetails: snapshot.providedUsageDetails,
      providedCostDetails: snapshot.providedCostDetails,
      toolDefinitions: convertDefinitionsToMap(toolDefinitions),
      toolCalls: toolCalls.tool_calls,
      toolCallNames: toolCalls.tool_call_names,
      input:
        snapshot.input !== undefined
          ? stringifyValue(snapshot.input)
          : undefined,
      output:
        snapshot.output !== undefined
          ? stringifyValue(snapshot.output)
          : undefined,
      metadata: snapshot.metadata,
      source,
      experimentId: experimentContext?.id,
      experimentName: experimentContext?.name,
      experimentMetadataNames: experimentMetadata.names,
      experimentMetadataValues: experimentMetadata.values,
      experimentDescription: experimentContext?.description ?? undefined,
      experimentDatasetId: experimentContext?.datasetId,
      experimentItemId: experimentContext?.itemId,
      experimentItemVersion: experimentContext?.itemVersion,
      experimentItemRootSpanId: experimentContext ? rootSpanId : undefined,
      experimentItemExpectedOutput:
        experimentContext?.itemExpectedOutput !== undefined &&
        experimentContext?.itemExpectedOutput !== null
          ? stringifyValue(experimentContext.itemExpectedOutput)
          : undefined,
      experimentItemMetadataNames: experimentItemMetadata.names,
      experimentItemMetadataValues: experimentItemMetadata.values,
    } satisfies InternalTraceEventInput;
  });

  return { rootSpanId, eventInputs };
}

import { useMemo } from "react";
import { api, sendAsPostOption } from "@/src/utils/api";
import {
  adaptEventsToTraceFormat,
  type AdaptedTraceData,
  type EventsTraceObservation,
} from "@/src/features/events/lib/eventsToTraceAdapter";
import {
  filterAndValidateDbScoreList,
  ScoreDataTypeArray,
  ScoreDataTypeEnum,
  type ScoreDomain,
} from "@langfuse/shared";
import {
  type WithStringifiedMetadata,
  toDomainArrayWithStringifiedMetadata,
} from "@/src/utils/clientSideDomainTypes";
import { partition } from "lodash";

interface UseEventsTraceDataProps {
  projectId: string;
  traceId: string;
  timestamp?: Date;
  enabled?: boolean;
}

interface UseEventsTraceDataResult {
  data:
    | (AdaptedTraceData["trace"] & {
        observations: AdaptedTraceData["observations"];
        scores: WithStringifiedMetadata<ScoreDomain>[];
        corrections: ScoreDomain[];
      })
    | undefined;
  isLoading: boolean;
  error: unknown;
  /**
   * The observation cap this trace was loaded under, set ONLY when the trace hit
   * it (so the list is missing its chronological tail). The number comes from the
   * server response — never a client-side copy of the constant.
   */
  truncatedAtObservations: number | undefined;
}

/**
 * Hook to fetch trace data from the events table instead of traces table.
 * Used when v4 beta mode is enabled.
 *
 * Data flow:
 * 1. Fetch all observations for the trace via events.all (without I/O)
 * 2. Find root observation (no parentObservationId)
 * 3. Fetch root observation's I/O via events.batchIO
 * 4. Fetch scores via getScoresAndCorrectionsForTraces
 * 5. Synthesize trace object from observations
 */
export function useEventsTraceData(
  props: UseEventsTraceDataProps,
): UseEventsTraceDataResult {
  const { projectId, traceId, enabled = true } = props;

  // Step 1: Fetch all observations for this trace (without I/O for performance)
  const eventsQuery = api.events.byTraceId.useQuery(
    {
      projectId,
      traceId,
      timestamp: props.timestamp,
    },
    {
      enabled: enabled && !!traceId,
      retry(failureCount, error) {
        if (error.data?.code === "UNAUTHORIZED") return false;
        return failureCount < 3;
      },
      staleTime: 60 * 1000, // 1 minute
    },
  );

  // Step 2: Find root observation and calculate time range for batchIO
  const observations = eventsQuery.data?.observations as
    | EventsTraceObservation[]
    | undefined;

  const rootObservation = useMemo(() => {
    if (!observations?.length) return null;
    return observations.find((o) => !o.parentObservationId);
  }, [observations]);

  // Prefer the root observation when present, otherwise fall back to the earliest one.
  const primaryObservation = useMemo(() => {
    if (!observations?.length) return null;
    if (rootObservation) return rootObservation;
    // Fallback to earliest observation
    return (
      [...observations].sort(
        (a, b) => a.startTime.getTime() - b.startTime.getTime(),
      )[0] ?? null
    );
  }, [observations, rootObservation]);

  const timeRange = useMemo(() => {
    if (!observations?.length) return null;
    const times = observations.map((o) => o.startTime.getTime());
    return {
      min: new Date(Math.min(...times)),
      max: new Date(Math.max(...times)),
    };
  }, [observations]);

  // Step 3: Fetch I/O for the primary trace observation.
  const rootIOQuery = api.events.batchIO.useQuery(
    {
      projectId,
      traceId,
      observations: primaryObservation
        ? [{ id: primaryObservation.id, traceId }]
        : [],
      minStartTime: timeRange?.min ?? new Date(),
      maxStartTime: timeRange?.max ?? new Date(),
      truncated: false,
    },
    {
      ...sendAsPostOption,
      enabled:
        enabled && !!primaryObservation && !!timeRange && !!eventsQuery.data,
      staleTime: 60 * 1000,
    },
  );

  // Step 4: Fetch scores for the trace
  const scoresQuery = api.events.scoresForTrace.useQuery(
    { traceId, projectId, timestamp: props.timestamp },
    {
      enabled: enabled && !!traceId,
      staleTime: 60 * 1000,
    },
  );

  // Step 5: Transform and merge data
  const transformed = useMemo(() => {
    if (!observations?.length) return null;

    // Validate and partition scores
    const validatedScores = filterAndValidateDbScoreList({
      scores: scoresQuery.data ?? [],
      dataTypes: [...ScoreDataTypeArray],
      onParseError: (e) => {
        console.error("[useEventsTraceData] Score validation error:", e);
      },
    });

    const [corrections, scores] = partition(
      validatedScores,
      (s) => s.dataType === ScoreDataTypeEnum.CORRECTION,
    );

    const scoresDomain = toDomainArrayWithStringifiedMetadata(scores);

    const rootIO = rootIOQuery.data?.[0];

    // Adapt events to trace format
    const adapted = adaptEventsToTraceFormat({
      events: observations,
      traceId,
      rootIO: rootIO
        ? {
            input: rootIO.input,
            output: rootIO.output,
            metadata: rootIO.metadata,
          }
        : undefined,
    });

    return {
      ...adapted.trace,
      observations: adapted.observations,
      scores: scoresDomain,
      corrections,
    };
  }, [observations, traceId, rootIOQuery.data, scoresQuery.data]);

  return {
    data: transformed ?? undefined,
    isLoading: eventsQuery.isLoading || scoresQuery.isLoading,
    error: eventsQuery.error || scoresQuery.error,
    truncatedAtObservations: eventsQuery.data?.cutoffObservationsAfterMaxCount
      ? eventsQuery.data.maxObservationsPerTrace
      : undefined,
  };
}

package fileauditor

import (
	"context"
	"log/slog"

	"github.com/SigNoz/signoz/pkg/errors"
	"github.com/SigNoz/signoz/pkg/types/audittypes"
)

func (provider *provider) export(ctx context.Context, events []audittypes.AuditEvent) error {
	logs := audittypes.NewPLogsFromAuditEvents(events, "signoz", provider.build.Version(), "signoz.audit")

	payload, err := provider.marshaler.MarshalLogs(logs)
	if err != nil {
		return err
	}

	// Combine the payload and trailing newline into one Write call so the line
	// is emitted in a single syscall — concurrent readers see either the full
	// line or nothing, never a torn JSON object.
	payload = append(payload, '\n')

	provider.mu.Lock()
	defer provider.mu.Unlock()

	if _, err := provider.file.Write(payload); err != nil {
		provider.settings.Logger().ErrorContext(ctx, "audit export failed", errors.Attr(err), slog.Int("dropped_log_records", len(events)))
		return err
	}

	return provider.file.Sync()
}

package otlphttpauditor

import (
	"bytes"
	"context"
	"io"
	"log/slog"
	"net/http"

	"github.com/SigNoz/signoz/pkg/auditor"
	"github.com/SigNoz/signoz/pkg/errors"
	"github.com/SigNoz/signoz/pkg/types/audittypes"
	collogspb "go.opentelemetry.io/proto/otlp/collector/logs/v1"
	"google.golang.org/protobuf/proto"

	spb "google.golang.org/genproto/googleapis/rpc/status"
)

const (
	maxHTTPResponseReadBytes int64  = 64 * 1024
	protobufContentType      string = "application/x-protobuf"
)

func (provider *provider) export(ctx context.Context, events []audittypes.AuditEvent) error {
	logs := audittypes.NewPLogsFromAuditEvents(events, "signoz", provider.build.Version(), "signoz.audit")

	request, err := provider.marshaler.MarshalLogs(logs)
	if err != nil {
		return errors.Wrapf(err, errors.TypeInternal, auditor.ErrCodeAuditExportFailed, "failed to marshal audit logs")
	}

	if err := provider.send(ctx, request); err != nil {
		provider.settings.Logger().ErrorContext(ctx, "audit export failed", errors.Attr(err), slog.Int("dropped_log_records", len(events)))
		return err
	}

	return nil
}

// Posts a protobuf-encoded OTLP request to the configured endpoint.
// Retries are handled by the underlying heimdall HTTP client.
// Ref: https://github.com/open-telemetry/opentelemetry-collector/blob/main/exporter/otlphttpexporter/otlp.go
func (provider *provider) send(ctx context.Context, body []byte) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, provider.config.OTLPHTTP.Endpoint.String(), bytes.NewReader(body))
	if err != nil {
		return err
	}

	req.Header.Set("Content-Type", protobufContentType)

	res, err := provider.httpClient.Do(req)
	if err != nil {
		return err
	}

	defer func() {
		_, _ = io.CopyN(io.Discard, res.Body, maxHTTPResponseReadBytes)
		res.Body.Close()
	}()

	if res.StatusCode >= 200 && res.StatusCode <= 299 {
		provider.onSuccess(ctx, res)
		return nil
	}

	return provider.onErr(res)
}

// Ref: https://github.com/open-telemetry/opentelemetry-collector/blob/01b07fcbb7a253bd996c290dcae6166e71d13732/exporter/otlphttpexporter/otlp.go#L403.
func (provider *provider) onSuccess(ctx context.Context, res *http.Response) {
	resBytes, err := readResponseBody(res)
	if err != nil || resBytes == nil {
		return
	}

	exportResponse := &collogspb.ExportLogsServiceResponse{}
	if err := proto.Unmarshal(resBytes, exportResponse); err != nil {
		return
	}

	ps := exportResponse.GetPartialSuccess()
	if ps == nil {
		return
	}

	if ps.GetErrorMessage() != "" || ps.GetRejectedLogRecords() != 0 {
		provider.settings.Logger().WarnContext(ctx, "partial success response", slog.String("message", ps.GetErrorMessage()), slog.Int64("dropped_log_records", ps.GetRejectedLogRecords()))
	}
}

func (provider *provider) onErr(res *http.Response) error {
	status := readResponseStatus(res)

	if status != nil {
		return errors.Newf(errors.TypeInternal, auditor.ErrCodeAuditExportFailed, "request to %s responded with status code %d, Message=%s, Details=%v", provider.config.OTLPHTTP.Endpoint.String(), res.StatusCode, status.Message, status.Details)
	}

	return errors.Newf(errors.TypeInternal, auditor.ErrCodeAuditExportFailed, "request to %s responded with status code %d", provider.config.OTLPHTTP.Endpoint.String(), res.StatusCode)
}

// Reads at most maxHTTPResponseReadBytes from the response body.
// Ref: https://github.com/open-telemetry/opentelemetry-collector/blob/01b07fcbb7a253bd996c290dcae6166e71d13732/exporter/otlphttpexporter/otlp.go#L275.
func readResponseBody(resp *http.Response) ([]byte, error) {
	if resp.ContentLength == 0 {
		return nil, nil
	}

	maxRead := resp.ContentLength
	if maxRead == -1 || maxRead > maxHTTPResponseReadBytes {
		maxRead = maxHTTPResponseReadBytes
	}

	protoBytes := make([]byte, maxRead)
	n, err := io.ReadFull(resp.Body, protoBytes)
	if n == 0 && (err == nil || errors.Is(err, io.EOF)) {
		return nil, nil
	}
	if err != nil && !errors.Is(err, io.ErrUnexpectedEOF) {
		return nil, err
	}

	return protoBytes[:n], nil
}

// Decodes a protobuf-encoded Status from 4xx/5xx response bodies. Returns nil if the response is empty or cannot be decoded.
// Ref: https://github.com/open-telemetry/opentelemetry-collector/blob/01b07fcbb7a253bd996c290dcae6166e71d13732/exporter/otlphttpexporter/otlp.go#L310.
func readResponseStatus(resp *http.Response) *spb.Status {
	if resp.StatusCode < 400 || resp.StatusCode > 599 {
		return nil
	}

	respBytes, err := readResponseBody(resp)
	if err != nil || respBytes == nil {
		return nil
	}

	respStatus := &spb.Status{}
	if err := proto.Unmarshal(respBytes, respStatus); err != nil {
		return nil
	}

	return respStatus
}

package opencensus

import (
	"go.opencensus.io/plugin/ochttp/propagation/b3"
	"go.opencensus.io/trace"
	"go.opencensus.io/trace/propagation"
)

// defaultHTTPPropagate holds OpenCensus' default HTTP propagation format which
// currently is Zipkin's B3.
var defaultHTTPPropagate propagation.HTTPFormat = &b3.HTTPFormat{}

// TracerOption allows for functional options to our OpenCensus tracing
// middleware.
type TracerOption func(o *TracerOptions)

// WithTracerConfig sets all configuration options at once.
func WithTracerConfig(options TracerOptions) TracerOption {
	return func(o *TracerOptions) {
		*o = options
	}
}

// WithSampler sets the sampler to use by our OpenCensus Tracer.
func WithSampler(sampler trace.Sampler) TracerOption {
	return func(o *TracerOptions) {
		o.Sampler = sampler
	}
}

// WithName sets the name for an instrumented transport endpoint. If name is omitted
// at tracing middleware creation, the method of the transport or transport rpc
// name is used.
func WithName(name string) TracerOption {
	return func(o *TracerOptions) {
		o.Name = name
	}
}

// IsPublic should be set to true for publicly accessible servers and for
// clients that should not propagate their current trace metadata.
// On the server side a new trace will always be started regardless of any
// trace metadata being found in the incoming request. If any trace metadata
// is found, it will be added as a linked trace instead.
func IsPublic(isPublic bool) TracerOption {
	return func(o *TracerOptions) {
		o.Public = isPublic
	}
}

// WithHTTPPropagation sets the propagation handlers for the HTTP transport
// middlewares. If used on a non HTTP transport this is a noop.
func WithHTTPPropagation(p propagation.HTTPFormat) TracerOption {
	return func(o *TracerOptions) {
		if p == nil {
			// reset to default OC HTTP format
			o.HTTPPropagate = defaultHTTPPropagate
			return
		}
		o.HTTPPropagate = p
	}
}

// TracerOptions holds configuration for our tracing middlewares
type TracerOptions struct {
	Sampler       trace.Sampler
	Name          string
	Public        bool
	HTTPPropagate propagation.HTTPFormat
}

